mapper.select:
select
comments.*,
student.stu_name,
student.stu_img,
s.stu_name as nickNameTo,
s.stu_img as headerImgTo
from comments comments
left join student student on comments.from_stu_id = student.id
left join (select * from student) s on s.id = comments.to_stu_id

    and comments.id = #{id}
    and comments.from_stu_id = #{fromStuId}
    and comments.content = #{content}
    and comments.to_stu_id = #{toStuId}
    and comments.parent_id = #{parentId}
    and comments.img_list = #{imgList}
    and comments.create_time = #{createTime}
    and comments.type = #{type}
    and student.stu_name like concat('%',#{stuName},'%')

order by id desc

    limit #{current},#{pageSize}

select count(*) from comments comments
left join student student on comments.from_stu_id = student.id
left join (select * from student) s on s.id = comments.to_stu_id

    and comments.id = #{id}
    and comments.from_stu_id = #{fromStuId}
    and comments.content = #{content}
    and comments.to_stu_id = #{toStuId}
    and comments.parent_id = #{parentId}
    and comments.img_list = #{imgList}
    and comments.create_time = #{createTime}
    and comments.type = #{type}
    and student.stu_name like concat('%',#{stuName},'%')

order by id desc
